def largestDivisibleSubset(nums):
    a = sorted(nums)
    n = len(a)
    size = [1] * n
    for i in range(n):
        x = a[i]
        best = 1
        for j in range(i):
            if x % a[j] == 0 and size[j] + 1 > best:
                best = size[j] + 1
        size[i] = best
    return max(size)
